---@return boolean
function CommunityDialog:IsUsedVuplexWebView()
    if Application.platform == RuntimePlatform.WindowsPlayer or Application.platform == RuntimePlatform.OSXPlayer then
        return true
    elseif Application.platform == RuntimePlatform.WindowsEditor or Application.platform == RuntimePlatform.OSXEditor then
        local BuildTarget = CS.UnityEditor.BuildTarget
        local enabledList = {
            BuildTarget.StandaloneOSXUniversal,
            BuildTarget.StandaloneOSXIntel,
            BuildTarget.StandaloneOSXIntel64,
            BuildTarget.StandaloneOSX,
            BuildTarget.StandaloneWindows64,
            BuildTarget.StandaloneWindows,
        }
        local activeBuildTarget = CS.UnityEditor.EditorUserBuildSettings.activeBuildTarget
        for _, target in ipairs(enabledList) do
            if activeBuildTarget == target then
                return true
            end
        end
    end
    return false
end

